import subprocess, itertools, string
chars = string.punctuation  # 32
cands=[]
for l in (2,3):
    for t in itertools.product(chars, repeat=l):
        cands.append(''.join(t))
print(len(cands))
# feed space-separated? but some involve spaces changes? Use line per candidate, batches
results={}
for i in range(0,len(cands),5000):
    batch=cands[i:i+5000]
    inp="\n".join(batch)+"\n"
    p=subprocess.run(["./executable","-S"], input=inp, capture_output=True, text=True)
    outs=p.stdout.splitlines()
    assert len(outs)==len(batch), (len(outs),len(batch))
    for c,o in zip(batch,outs):
        if c!=o: results[c]=o
for c,o in results.items(): print(repr(c),"->",repr(o))
print("count",len(results))
PY"}

