    if node_type=='type_item': return [tok_range(st,it['a'],it['b']) for it in items if it['kind']=='type']
    if node_type=='enum_variant': return rust_ranges(text,'enum-variant')
    if node_type=='source_file': return [(0,len(text))]
    if node_type=='call_expression':
        out=[]
        for i,t in enumerate(st):
