def _rust_comment_ranges(toks, doc=False):
    # Group consecutive line-comment-only lines: a run of comment tokens that each start a line and are on consecutive lines.
    comments=[t for t in toks if t.kind=='comment']
    # line number via count newlines before (we can infer from token order and nl tokens in toks)
    # Build map token -> line index and whether it's line-leading (prev non-comment token is nl/start)
    line=0; info={}
    prev_sig_kind=None
