    for t in toks:
        if t.kind=='nl':
            line+=1; at_line_start=True; continue
        if t.kind=='comment' and t.text.startswith('//'):
            info[id(t)]=(line, at_line_start)
        else:
            at_line_start=False
    # group line comments
    out=[]; used=set()
    line_comments=[t for t in comments if t.text.startswith('//')]
    # runs by consecutive lines and line-leading
    runs=[]; cur=[]
    for t in line_comments:
        ln, leading=info.get(id(t),(0,False))
        if cur and leading and info.get(id(cur[-1]),(ln-10,False))[1] and ln==info.get(id(cur[-1]))[0]+1:
            cur.append(t)
        else:
            if cur: runs.append(cur)
            cur=[t]
    if cur: runs.append(cur)
    def cls(txt):
        if txt.startswith('//!'): return 'inner'
        if txt.startswith('///'): return 'doc'
        return 'plain'
    run_ids=set()
    for run in runs:
        classes={cls(t.text) for t in run}
        for t in run: run_ids.add(id(t))
        if len(classes)!=1:
            continue
        c=next(iter(classes))
        if not doc and c in ('plain','inner'):
            out.extend((t.start,t.end) for t in run)
        if doc and c in ('doc','inner'):
            out.extend((t.start,t.end) for t in run)
    # block comments: comments only
    if not doc:
        for t in comments:
            if t.text.startswith('/*'):
                out.append((t.start,t.end))
    return out

