        for t in run: run_ids.add(id(t))
        if len(classes)!=1:
            continue
        c=next(iter(classes))
        if not doc and c in ('plain','inner'):
            out.extend((t.start,t.end) for t in run)
        if doc and c in ('doc','inner'):
            out.extend((t.start,t.end) for t in run)
    # block comments: comments only
    if not doc:
        for t in comments:
            if t.text.startswith('/*'):
                out.append((t.start,t.end))
    return out

def _item_start_before(st, kw_idx):
    """Walk backwards over visibility/modifiers from keyword token index kw_idx; return (start_idx, vis, mods_set, extern_string?)"""
    i=kw_idx-1; start=kw_idx; vis=None; mods=set()
    # tokens that can precede a definition within same item
    while i>=0:
        t=st[i]
        if t.text==')':
            # pub(crate) etc: find matching '(' backwards simply scan
            depth=0; j=i
            while j>=0:
                if st[j].text==')': depth+=1
                elif st[j].text=='(':
                    depth-=1
                    if depth==0: break
                j-=1
            if j>0 and st[j-1].text=='pub':
                content=''.join(x.text for x in st[j+1:i])
                vis=f"pub({content})"; start=j-1; i=j-2; continue
            break
        if t.kind=='ident' and t.text=='pub':
            vis='pub'; start=i; i-=1; continue
        if t.kind=='ident' and t.text in ('const','async','unsafe','default','extern','gen'):
            mods.add(t.text); start=i; i-=1; continue
        if t.kind=='string' and i>0 and st[i-1].text=='extern':
            # e.g. extern "C" fn - string sits between extern and fn: when walking back from fn, previous token is string
            start=i-1; mods.add('extern'); i-=2; continue
        break
    return start,vis,mods

def _rust_items(text):
    toks=lex_clike(text,'rust'); st=sig(toks); pairs=matching_braces(st)
    items=[]  # dict kind range_tok (a,b inclusive), name, vis, mods, kw_idx, body (a,b) etc
    n=len(st)
    def item_end(kw_idx, kind):
        # Scan forward for body '{' or ';' at paren/bracket depth 0, respecting function params etc
        depth_par=0; depth_br=0; i=kw_idx
        angle=0
        while i<n:
            t=st[i]
            if t.text=='(': depth_par+=1
            elif t.text==')': depth_par-=1
            elif t.text=='[': depth_br+=1
            elif t.text==']': depth_br-=1
            elif depth_par==0 and depth_br==0 and t.text=='{':
                ci=find_matching(st,pairs,i)
                if ci is None: return i,i
                # For tuple struct etc, '{' marks body; end here except struct handled separately maybe before '('
                return ci,i
            elif depth_par==0 and depth_br==0 and t.text==';':
                return i,None
            i+=1
        return n-1,None
    i=0
    for idx,t in enumerate(st):
        if t.kind!='ident':
            continue
        kw=t.text
        if kw in ('struct','enum','union','trait','impl','mod','fn','type'):
            # fn needs a name after
            start,vis,mods=_item_start_before(st,idx)
            name=None; name_idx=None
            if kw=='impl':
                pass
            elif kw=='fn':
                if idx+1<n and st[idx+1].kind=='ident':
                    name=st[idx+1].text; name_idx=idx+1
                else:
                    continue
            else:
                if idx+1<n and st[idx+1].kind=='ident':
                    name=st[idx+1].text; name_idx=idx+1
                else:
                    # trait/impl may have generics; type needs name
                    if kw in ('struct','enum','union','trait','mod','type'):
                        continue
            # Special struct: can end with '(' tuple body then ; or '{' fields or ';'
            end=None; body_open=None
            if kw=='struct':
                # scan for first '{','(',';' at angle depth (where clause may contain {})
                j=idx+1; par=0; br=0
                while j<n:
                    tt=st[j]
                    if tt.text=='(' and par==0:
                        # tuple struct ends at matching ) then possibly ; (required) - include ; if next
                        ci=find_matching(st,pairs,j)
                        if ci is None: end=j; break
                        end=ci+1 if ci+1<n and st[ci+1].text==';' else ci
                        break
                    if tt.text=='[': br+=1
                    elif tt.text==']': br-=1
                    elif tt.text=='{' and par==0 and br==0:
                        ci=find_matching(st,pairs,j); end=ci if ci is not None else j; body_open=j; break
                    elif tt.text==';' and par==0 and br==0:
                        end=j; break
                    j+=1
                if end is None: end=n-1
            elif kw=='fn':
                # Find body or ';' but struct literals in default etc unlikely in signature; find '{' at par depth0
                end,body_open=item_end(idx,kw)
                if body_open is None:
                    # signature only
                    items.append({'kind':'fn_sig','a':start,'b':end,'name':name,'name_idx':name_idx,'vis':vis,'mods':mods,'kw':idx,'body_open':None})
                    continue
            elif kw=='impl':
                end,body_open=item_end(idx,kw)
            elif kw=='mod':
                end,body_open=item_end(idx,kw)
            elif kw=='type':
                # type alias ends ';' at depth0 (brace could be in definition? no)
                j=idx; par=0; br=0; brace=0; end=n-1
                while j<n:
                    tt=st[j]
                    if tt.text=='(' : par+=1
                    elif tt.text==')': par-=1
                    elif tt.text=='[': br+=1
                    elif tt.text==']': br-=1
                    elif tt.text=='{': brace+=1
                    elif tt.text=='}': brace-=1
                    elif tt.text==';' and par==0 and br==0 and brace==0:
                        end=j; break
                    j+=1
            else:
                end,body_open=item_end(idx,kw)
            items.append({'kind':kw,'a':start,'b':end,'name':name,'name_idx':name_idx,'vis':vis,'mods':mods,'kw':idx,'body_open':body_open})
    return toks,st,pairs,items

def _rust_attributes(st):
    attrs=[]  # (hash_idx, bracket_open_idx, bracket_close_idx, inner_start_range, inner_text)
    n=len(st); pairs=matching_braces(st)
    for i,t in enumerate(st):
        if t.text=='#' and i+1<n and st[i+1].text=='[':
            ci=find_matching(st,pairs,i+1)
            if ci is not None:
                attrs.append((i,i+1,ci))
        if t.text=='#' and i+2<n and st[i+1].text=='!' and st[i+2].text=='[':
            ci=find_matching(st,pairs,i+2)
            if ci is not None:
                attrs.append((i,i+2,ci))
    return attrs

def rust_ranges(text, scope, pattern=None):
    toks=lex_clike(text,'rust'); st=sig(toks); pairs=matching_braces(st)
    if scope=='comments': return _rust_comment_ranges(toks,doc=False)
    if scope=='doc-comments': return _rust_comment_ranges(toks,doc=True)
    if scope=='strings':
        out=[]
        for t in st:
            if t.kind=='string': out.extend(t.frags)
        return out
    if scope=='attribute':
        out=[]
        for h,o,c in _rust_attributes(st):
            if o+1<=c-1: out.append(tok_range(st,o+1,c-1))
        return [r for r in out if r]
    if scope=='uses':
        out=[]
        for i,t in enumerate(st):
            if t.kind=='ident' and t.text=='use':
                # argument from after use to before ';'
                j=i+1; brace=0
                while j<len(st) and st[j].text!=';':
                    j+=1
                if j>i+1:
                    out.append(tok_range(st,i+1,j-1))
        return [r for r in out if r]
    _,st2,pairs2,items=_rust_items(text)  # st identical
    # helper ranges
    def irange(item): return tok_range(st,item['a'],item['b'])
    if scope in ('struct','enum','trait','mod') or scope.startswith(('priv-struct','pub')) or scope in ('type-def',):
        out=[]
        for it in items:
            kind=it['kind']
            if scope=='type-def' and kind in ('struct','enum','union'):
                out.append(irange(it)); continue
            if scope in ('struct','enum','trait','mod'):
                if kind==scope:
                    if pattern is not None:
                        if it['name'] and pattern.search(it['name']): out.append(irange(it))
                    else: out.append(irange(it))
                continue
            # priv/pub variants
            m=re.match(r'(priv|pub|pub-crate|pub-self|pub-super)-(struct|enum|fn)$',scope)
            if m:
                want_vis,want_kind=m.group(1),m.group(2)
                if kind!=want_kind: continue
                vis=it['vis']
                ok=False
                if want_vis=='priv': ok=vis is None
                elif want_vis=='pub': ok=vis=='pub'
                else: ok=vis==want_vis.replace('pub-','pub(')+')' if False else vis==f"pub({want_vis[4:]})"
                if ok: out.append(irange(it))
        return [r for r in out if r]
    if scope=='enum-variant':
        out=[]
        for it in items:
            if it['kind']!='enum' or it['body_open'] is None: continue
            bo=it['body_open']; bc=find_matching(st,pairs,bo)
            if bc is None: continue
            for a,b in _split_top_level(st,bo+1,bc-1,','):
                out.append(tok_range(st,a,b))
        return [r for r in out if r]
    if scope in ('fn','impl-fn','priv-fn','pub-fn','pub-crate-fn','pub-self-fn','pub-super-fn','const-fn','async-fn','unsafe-fn','extern-fn','test-fn'):
        impl_ranges=[(it['body_open'], find_matching(st,pairs,it['body_open'])) for it in items if it['kind']=='impl' and it['body_open'] is not None]
        attrs=_rust_attributes(st)
        # attribute associations: attr ends before item start with only attrs between, and no ';'/'}' etc item boundary max? Use preceding attrs chain.
        def has_test_attr(item):
            # walk backward over attrs whose close is immediately before an attrs chain ending at item start token index
            cur=item['a']
            found=[]
            changed=True
            # collect attrs in reverse contiguous token sequence (doc-comments/attrs not sig; comments excluded anyway)
            idxs={c:(h,o,c) for h,o,c in attrs}
            while True:
                # find attr with close == cur-1
                cand=None
                for h,o,c in attrs:
                    if c==cur-1: cand=(h,o,c); break
                if not cand: break
                found.append(cand); cur=cand[0]
            for h,o,c in found:
                inner=text[st[o].end:st[c].start] if o+1<=c else ''
                inner_tokens=''.join(x.text for x in st[o+1:c])
                if 'test' in inner_tokens: return True
            return False
        out=[]
        for it in items:
            if it['kind']!='fn': continue
            if scope=='fn':
                if pattern is not None:
                    if it['name'] and pattern.search(it['name']): out.append(irange(it))
                else: out.append(irange(it))
            elif scope=='impl-fn':
                if any(bo is not None and bc is not None and bo<it['kw']<bc for bo,bc in impl_ranges): out.append(irange(it))
            elif scope=='priv-fn':
                if it['vis'] is None and not it['mods'] and it['a']==it['kw']: out.append(irange(it))
            elif scope=='pub-fn':
                if it['vis']=='pub': out.append(irange(it))
            elif scope.startswith('pub-'):
                want='pub('+scope.split('-')[1]+')'
                if it['vis']==want: out.append(irange(it))
            elif scope=='const-fn':
                if 'const' in it['mods']: out.append(irange(it))
            elif scope=='async-fn':
                if 'async' in it['mods']: out.append(irange(it))
            elif scope=='unsafe-fn':
                if 'unsafe' in it['mods']: out.append(irange(it))
            elif scope=='extern-fn':
                if 'extern' in it['mods']: out.append(irange(it))
            elif scope=='test-fn':
                if has_test_attr(it): out.append(irange(it))
        return [r for r in out if r]
    if scope in ('impl','impl-type','impl-trait'):
        out=[]
        for it in items:
            if it['kind']!='impl': continue
            # is trait impl if 'for' at top level before body_open (outside <>()?) scan tokens between kw and body/{; for ident 'for' after a type with angle depth0
            is_trait=False; j=it['kw']+1; adepth=0
            endh=it['body_open'] if it['body_open'] is not None else it['b']
            while j<endh:
                if st[j].text=='<': adepth+=1
                elif st[j].text=='>': adepth=max(0,adepth-1)
                elif adepth==0 and st[j].kind=='ident' and st[j].text=='for': is_trait=True; break
                j+=1
            if scope=='impl' or (scope=='impl-trait' and is_trait) or (scope=='impl-type' and not is_trait): out.append(irange(it))
        return [r for r in out if r]
    if scope=='mod-tests':
        return [irange(it) for it in items if it['kind']=='mod' and it['name']=='tests']
    if scope=='closure':
        return _rust_closures(text,st,pairs)
    if scope=='unsafe':
        out=[]
        for it in items:
            if 'unsafe' in it['mods'] and it['kind'] in ('fn','trait','impl'):
                out.append(irange(it))
        # unsafe blocks
        for i,t in enumerate(st):
            if t.kind=='ident' and t.text=='unsafe' and i+1<len(st) and st[i+1].text=='{':
                ci=find_matching(st,pairs,i+1)
                if ci is not None: out.append(tok_range(st,i,ci))
        return [r for r in out if r]
    if scope in ('identifier','type-identifier'):
        return _rust_identifiers(text,st,pairs,items,types=(scope=='type-identifier'))
    return []

def _rust_closures(text,st,pairs):
    out=[]; n=len(st)
    i=0
    while i<n:
        # start at '|' or '||' (tokenised as || op if attached) or "move |"
        start=None; pipe_idx=None; empty=False
        if st[i].text=='||':
            start=i; pipe_idx=i; empty=True
        elif st[i].text=='|' :
            start=i; pipe_idx=i
        elif st[i].text=='move' and i+1<n and st[i+1].text in ('|','||'):
            start=i; pipe_idx=i+1; empty=st[i+1].text=='||'
        elif st[i].text=='async' and i+2<n and st[i+1].text=='move' and st[i+2].text in ('|','||'):
            start=i; pipe_idx=i+2; empty=st[i+2].text=='||'
        if start is None:
            i+=1; continue
        # previous token should signal expression context
        prev=st[start-1] if start>0 else None
        if prev is not None and prev.kind in ('ident','number','string') and prev.text not in ('return','='):
            i+=1; continue
        if empty:
            body_start=pipe_idx+1
        else:
            # find closing '|' single token (not in nested closure params types: simple search)
            j=pipe_idx+1; depth_other=0; close=None
            while j<n:
                if st[j].text in ('(','[','{'): depth_other+=1
                elif st[j].text in (')',']','}'):
                    if depth_other==0: break
                    depth_other-=1
                elif st[j].text=='|' and depth_other==0:
                    close=j; break
                elif st[j].text==';' and depth_other==0:
                    break
                j+=1
            if close is None:
                i+=1; continue
            body_start=close+1
        # optional return type -> Type (skip until body) - find arrow; if next is '->', skip type tokens until '{' or an expression token? Simplistic: if '{' later before ';'/',' at depth0 use it.
        body_idx=body_start
        if body_idx<n and st[body_idx].text=='->':
            # seek '{' at depth0 before boundary; if none, body expression starts after type tokens that form a type: assume next block else skip one type token chain
            k=body_idx+1; d=0; brace=None
            while k<n:
                if st[k].text in ('(','['): d+=1
                elif st[k].text in (')',']'): d-=1
                elif st[k].text=='{' and d==0: brace=k; break
                elif st[k].text in (';',',') and d==0: break
                k+=1
            body_idx=brace if brace is not None else body_idx+1
        if body_idx<n and st[body_idx].text=='{':
            ci=find_matching(st,pairs,body_idx); end=ci if ci is not None else body_idx
            out.append(tok_range(st,start,end)); i=end+1; continue
        # expression body until ','/';'/ closing delimiter at depth0
        j=body_idx; d=0; last=body_idx
        while j<n:
            if st[j].text in ('(','[','{'): d+=1
            elif st[j].text in (')',']','}'):
                if d==0: break
                d-=1
            elif d==0 and st[j].text in (';',','):
                break
            last=j; j+=1
        if body_idx<n:
            out.append(tok_range(st,start,last))
        i=max(i+1,last+1)
    return [r for r in out if r]

def _rust_identifiers(text,st,pairs,items,types=False):
    # Collect type identifier token indices
    type_ids=set(); ident_exclude=set()
    # definition names of types/trait/type items
    for it in items:
        if it['kind'] in ('struct','enum','union','trait','type') and it['name_idx'] is not None:
            type_ids.add(it['name_idx'])
    # type positions helpers
    n=len(st)
    def collect_type_expr(start_idx, stop_texts):
        # collect identifiers in a type expression until a stop token at depth0 of <> relative? Just walk until delimiters at nesting0
        j=start_idx; depth=0
        while j<n:
            t=st[j]
            if t.text in ('(','[','<'): depth += 1 if t.text!='<' else 0
            if depth==0 and t.text in stop_texts:
                break
            if t.kind=='ident' and t.text not in _RUST_KEYWORDS and t.text not in _RUST_PRIMITIVES:
                # ignore primitive and lifetimes; a type identifier if token in type chain (preceded/followed by ::, <, >, comma, &, etc) - accept all non-keyword in span except associated names after ::? In Vec<String>, both accepted.
                type_ids.add(j)
            if t.text in (')',']'): depth=max(0,depth-1)
            j+=1
        return j
    for i,t in enumerate(st):
        # after ':' in fields/params/bindings: collect until ',', '=', ')', ';', '{'(for where?) but pattern ':' in expressions also struct literals - struct literal field type none. Use heuristics: ':' follows identifier and previous context inside parens / struct body / let, still adding uppercase types only here to limit
        if t.text==':' and i+1<n and (i==0 or st[i-1].text!=':'):
            # collect capitalized/generic identifiers until top-level terminator
            j=i+1; d=0
            while j<n:
                tt=st[j]
                if tt.text in ('(','[','<'): d+= (1 if tt.text in ('(','[') else 0)
                if d==0 and tt.text in (',','=',';',')','{'):
                    if tt.text=='{' and j>i+1: break
                    if tt.text in (',','=',';',')'): break
                if tt.kind=='ident' and tt.text not in _RUST_KEYWORDS and tt.text not in _RUST_PRIMITIVES:
                    if tt.text[:1].isupper() or (j+1<n and st[j+1].text in ('<','::')) or (j>0 and st[j-1].text in ('<','::',',','&')):
                        type_ids.add(j)
                if tt.text in (')',']'): d=max(0,d-1)
                j+=1
        if t.text=='->' and i+1<n:
            j=i+1; d=0
            while j<n and st[j].text not in ('{',';','where'):
                tt=st[j]
                if tt.kind=='ident' and tt.text not in _RUST_KEYWORDS and tt.text not in _RUST_PRIMITIVES:
                    if tt.text[:1].isupper() or (j+1<n and st[j+1].text in ('<','::')) or (j>0 and st[j-1].text in ('<','::',',')):
                        type_ids.add(j)
                j+=1
    # impl headers: identifiers between impl and body which are capitalized/path
    for it in items:
        if it['kind']=='impl':
            endh=it['body_open'] if it['body_open'] is not None else it['b']
            for j in range(it['kw']+1,endh):
                if st[j].kind=='ident' and st[j].text not in _RUST_KEYWORDS and st[j].text not in _RUST_PRIMITIVES:
                    if st[j].text[:1].isupper(): type_ids.add(j)
        if it['kind']=='type':
            # RHS type identidiers
            j=it['kw']+1
            # skip name & generics to '='
            while j<=it['b'] and st[j].text!='=': j+=1
            for k in range(j+1,it['b']+1):
                if st[k].kind=='ident' and st[k].text not in _RUST_KEYWORDS and st[k].text not in _RUST_PRIMITIVES:
                    type_ids.add(k)
    # struct literals: Ident followed by '{' where Ident not keyword/control and previous token is =/(/,/return etc and inside brace look field-ish: accept Capitalized
    for i,t in enumerate(st):
        if t.kind=='ident' and t.text[:1].isupper() and i+1<n and st[i+1].text=='{':
            prev=st[i-1] if i>0 else None
            if prev is None or prev.text in ('=', '(', ',', 'return', ':', '[', '=>','!','?','&&','||') or prev.kind=='ident' and prev.text in ('return','let'):
                type_ids.add(i)
    if types:
        return [ (st[i].start,st[i].end) for i in sorted(type_ids)]
    out=[]
    # field identifiers exclusion: after '.' (but not '..'), and identifiers in struct field definition lines / struct literals followed by ':' (field names)
    field_ids=set()
    for i,t in enumerate(st):
        if t.kind!='ident': continue
        if i>0 and st[i-1].text=='.':
            field_ids.add(i)
        # field name in struct definitions / initialisers: ident ':' where enclosing construct is struct/enum... rough: ident followed ':' and next token ident capitalized/primitive and preceded by '{' or ','
        if i+1<n and st[i+1].text==':' and i>0 and st[i-1].text in ('{',','):
            field_ids.add(i)
    for i,t in enumerate(st):
        if t.kind!='ident': continue
        name=t.text
        base=name[2:] if name.startswith('r#') else name
        if base in _RUST_KEYWORDS: continue
        if i in type_ids: continue
        if i in field_ids: continue
        if base in _RUST_PRIMITIVES: continue
        out.append((t.start,t.end))
    return out

def rust_node_ranges(text,node_type):
    # map tree-sitter node names to approximations
    toks=lex_clike(text,'rust'); st=sig(toks); pairs=matching_braces(st); _t,_s,_p,items=_rust_items(text)
    if node_type in ('line_comment','block_comment'):
        return [(t.start,t.end) for t in toks if t.kind=='comment' and (t.text.startswith('//') if node_type=='line_comment' else t.text.startswith('/*'))]
    if node_type in ('string_literal','raw_string_literal'):
        return [(t.start,t.end) for t in st if t.kind=='string']
    if node_type=='char_literal': return [(t.start,t.end) for t in st if t.kind=='char']
    if node_type=='identifier': return rust_ranges(text,'identifier')
    if node_type=='type_identifier': return rust_ranges(text,'type-identifier')
    if node_type=='field_identifier':
        return [(st[i].start,st[i].end) for i,t in enumerate(st) if t.kind=='ident' and i>0 and st[i-1].text=='.']
    map_item={'function_item':'fn','struct_item':'struct','enum_item':'enum','trait_item':'trait','impl_item':'impl','mod_item':'mod','union_item':None}
    if node_type in map_item:
        if node_type=='union_item': return [tok_range(st,it['a'],it['b']) for it in items if it['kind']=='union']
        kind=map_item[node_type]; return [tok_range(st,it['a'],it['b']) for it in items if it['kind']==kind]
    if node_type=='use_declaration':
        out=[]
        for i,t in enumerate(st):
            if t.kind=='ident' and t.text=='use':
                s,_vis,_mods=_item_start_before(st,i); j=i
                while j<len(st) and st[j].text!=';': j+=1
                out.append(tok_range(st,s,min(j,len(st)-1)))
        return [r for r in out if r]
    if node_type=='closure_expression': return rust_ranges(text,'closure')
