    if scope=='strings':
        out=[]
        for t in st:
            if t.kind=='string': out.extend(t.frags)
        return out
    if scope=='imports':
        out=[]
        for i,t in enumerate(st):
            if t.kind=='ident' and t.text=='import':
                # import(...) dynamic: string arg? imports scope likely declarations only; include statement strings until ';'/line next import
                if i+1<n and st[i+1].text=='(':
                    continue
                j=i+1
                while j<n and st[j].text!=';':
                    if st[j].kind=='string': out.extend(st[j].frags)
                    # stop at next statement keyword on new logical segment if no semicolon? look ahead for 'from' done then string captured
                    j+=1
                    if out: break
                # Actually we break after first string; above loop breaks
        return out
    funcs=_ts_funcs(st,pairs); classes=_ts_classes(st,pairs)
    if scope in ('function','async-function','sync-function'):
        out=[]
