            # range from 'function'/'async function' (not export). async func start includes async.
            if scope=='function' or (scope=='async-function' and f['async']) or (scope=='sync-function' and not f['async']):
                out.append(tok_range(st,f['start'],f['b']))
        return [r for r in out if r]
    if scope=='class':
        return [tok_range(st,c['start'],c['b']) for c in classes]
    if scope in ('method','constructor'):
        methods=_ts_methods(st,pairs,classes)
        if scope=='method': return [tok_range(st,m['a'],m['b']) for m in methods]
        return [tok_range(st,m['a'],m['b']) for m in methods if m['name']=='constructor']
    if scope in ('enum','interface'):
        out=[]
        for i,t in enumerate(st):
