        off=tokens[idx][1] if idx<len(tokens) else n
        line=query.count('\n',0,off)+1; lastnl=query.rfind('\n',0,off); col=off-lastnl
        lines=query.splitlines()
        linetext=lines[line-1] if line-1<len(lines) else ''
        if kind=='syntax':
            raise QueryError(f"Query error at {line}:{col}. Invalid syntax:\n{linetext}\n{' '*(col-1)}^")
    # check balance and that query starts with '(' or '[' (tree-sitter queries can also start with a node literal? top-level patterns start '(')
    if tokens[0][0] not in ('(','['):
