    valid=VALID_NODES.get(lang,set())
    for idx,(tok,off) in enumerate(tokens):
        if tok=='(' or tok=='[':
            stack.append(tok)
            if tok=='(' and idx+1<len(tokens):
                nxt=tokens[idx+1][0]
