    # Build nested list structure from tokens (strings kept raw)
    pos=0
    def parse_expr():
        nonlocal pos
        if pos>=len(tokens): return None
        tok=tokens[pos][0]; pos+=1
        if tok=='(':
            lst=[]
            while pos<len(tokens) and tokens[pos][0]!=')':
                lst.append(parse_expr())
            if pos<len(tokens): pos+=1
