                lines=query.splitlines() or ['']
                raise QueryError(f"Query error at {line}:{col}. Invalid syntax:\n{lines[line-1]}\n{' '*(col-1)}^")
            tokens.append((query[i:j+1],i)); i=j+1; continue
        j=i
        while j<n and not query[j].isspace() and query[j] not in '()[];':
            j+=1
        tokens.append((query[i:j],i)); i=j
    if not tokens:
        return tokens
    # simple full parse
    pos=0
    def err_at(idx, kind='syntax'):
        off=tokens[idx][1] if idx<len(tokens) else n
        line=query.count('\n',0,off)+1; lastnl=query.rfind('\n',0,off); col=off-lastnl
        lines=query.splitlines()
        linetext=lines[line-1] if line-1<len(lines) else ''
        if kind=='syntax':
            raise QueryError(f"Query error at {line}:{col}. Invalid syntax:\n{linetext}\n{' '*(col-1)}^")
    # check balance and that query starts with '(' or '[' (tree-sitter queries can also start with a node literal? top-level patterns start '(')
    if tokens[0][0] not in ('(','['):
        err_at(0)
    stack=[]
    valid=VALID_NODES.get(lang,set())
    for idx,(tok,off) in enumerate(tokens):
        if tok=='(' or tok=='[':
            stack.append(tok)
            if tok=='(' and idx+1<len(tokens):
                nxt=tokens[idx+1][0]
                # predicate (#x) ok; anonymous or wildcard _ ok; node name validate
                if nxt.startswith('#') or nxt=='_' or nxt.startswith('"') or nxt in ('(','['):
                    pass
                elif re.fullmatch(r'[A-Za-z_][A-Za-z0-9_\-]*',nxt):
                    if nxt not in valid:
                        line=query.count('\n',0,tokens[idx+1][1])+1; lastnl=query.rfind('\n',0,tokens[idx+1][1]); col=tokens[idx+1][1]-lastnl
                        raise QueryError(f"Query error at {line}:{col}. Invalid node type {nxt}")
                else:
                    err_at(idx+1)
        elif tok==')' or tok==']':
            if not stack: err_at(idx)
            op=stack.pop()
            if (op=='(' and tok!=')') or (op=='[' and tok!=']'): err_at(idx)
    if stack:
        err_at(len(tokens)-1)
