def _parse_query_patterns(tokens, query):
    # Build nested list structure from tokens (strings kept raw)
    pos=0
    def parse_expr():
        nonlocal pos
        if pos>=len(tokens): return None
        tok=tokens[pos][0]; pos+=1
        if tok=='(':
            lst=[]
            while pos<len(tokens) and tokens[pos][0]!=')':
                lst.append(parse_expr())
            if pos<len(tokens): pos+=1
            return ('list',lst)
        if tok=='[':
            lst=[]
            while pos<len(tokens) and tokens[pos][0]!=']':
                lst.append(parse_expr())
            if pos<len(tokens): pos+=1
            return ('alt',lst)
        if tok in (')',']'):
            return None
        return ('atom',tok)
    patterns=[]
    while pos<len(tokens):
        e=parse_expr()
        if e is not None: patterns.append(e)
    return patterns

def custom_query_ranges(lang, text, query):
    tokens=validate_query(lang,query)
    if not tokens: return []
    patterns=_parse_query_patterns(tokens,query)
    node_fn=NODE_RANGES[lang]
    out=[]
    def eval_expr(expr, context_ranges=None):
        """Return captured ranges for expression, constrained to context ranges if given (containment)."""
        kind,val=expr
        captures=[]
        if kind=='atom':
            return captures
        if kind=='alt':
            for sub in val:
                captures.extend(eval_expr(sub,context_ranges))
            return captures
        # list: pattern
        items=val
        if not items: return captures
        head=items[0]
        if head[0]=='atom' and head[1].startswith('#'):
            return captures  # predicates handled at parent level
        node_ranges_here=None
        child_context=context_ranges
        if head[0]=='atom' and head[1]!='_':
            nt=head[1]
            if nt.startswith('"'):
                return captures  # anonymous keyword nodes unsupported
            try:
                node_ranges_here=node_fn(text,nt)
            except Exception:
                node_ranges_here=[]
            if context_ranges is not None:
                node_ranges_here=[r for r in node_ranges_here if any(cs<=r[0] and r[1]<=ce for cs,ce in context_ranges)]
            child_context=node_ranges_here
        # children & trailing captures
        trailing_captures=[]
        for sub in items[1:]:
            if sub[0]=='atom':
                if sub[1].startswith('@'):
                    trailing_captures.append(sub[1][1:])
                # field labels / quantifiers ignored
                continue
            captures.extend(eval_expr(sub,child_context))
        if trailing_captures and node_ranges_here is not None:
            captures.extend(node_ranges_here)
        return captures
    # Predicate filtering for simple patterns: ((x) @c (#match? @c "re")) - collect top-level predicates
    def get_predicates(pattern):
        preds=[]
        def walk(e):
            if e[0]=='list' and e[1] and e[1][0][0]=='atom' and e[1][0][1].startswith('#'):
                atoms=[x[1] for x in e[1] if x[0]=='atom']
                preds.append(atoms); return
            if e[0] in ('list','alt'):
                for s in e[1]: walk(s)
        walk(pattern); return preds
    for pat in patterns:
        ranges=eval_expr(pat)
        preds=get_predicates(pat)
        for atoms in preds:
            if len(atoms)>=3:
                op=atoms[0].lstrip('#'); val=atoms[2].strip('"')
                try:
                    val_processed=bytes(val,'utf-8').decode('unicode_escape') if '\\' in val else val
                except Exception:
                    val_processed=val
                if op in ('match?','not-match?'):
                    try: rx=re.compile(val_processed)
                    except Exception: rx=None
                    if rx:
                        if op=='match?': ranges=[r for r in ranges if rx.search(text[r[0]:r[1]])]
                        else: ranges=[r for r in ranges if not rx.search(text[r[0]:r[1]])]
                elif op in ('eq?','not-eq?'):
                    if op=='eq?': ranges=[r for r in ranges if text[r[0]:r[1]]==val_processed]
                    else: ranges=[r for r in ranges if text[r[0]:r[1]]!=val_processed]
        out.extend(ranges)
    return out
