class Args:
    def __init__(self):
        self.scope=".*"; self.scope_explicit=False
        self.replacement=None; self.replacement_explicit=False
        vals={}
        for o in OPTS:
            if o.kind=='bool': vals[o.dest]=False
            elif o.kind=='count': vals[o.dest]=0
            elif o.kind=='value': vals[o.dest]=None
        self.vals=vals
        self.lang={lang:{'prepared':[],'query':[],'query_file':[]} for lang in LANG_VALUES}
        self.events=[]  # (opt or 'scope'/'replacement', token display)
        self.present=set()  # dests / lang keys like lang:python:prepared
    def __getattr__(self,name):
        if name in self.__dict__.get('vals',{}): return self.vals[name]
        raise AttributeError(name)
    def has_language(self):
        return any(v['prepared'] or v['query'] or v['query_file'] for v in self.lang.values())
    def language_names(self):
        return [k for k,v in self.lang.items() if v['prepared'] or v['query'] or v['query_file']]

def _suggest_usage(suggested_long):
    o=LONG_MAP.get(suggested_long)
    if o is None: return _usage()
    if o.group=='composable':
        return f"Usage: {BIN_NAME} <REPLACEMENT|--upper|--lower|--titlecase|--normalize|--german|--symbols> [SCOPE]"
    if o.group=='standalone':
        return f"Usage: {BIN_NAME} <--delete|--squeeze> [SCOPE] [-- <REPLACEMENT>]"
    if o.group=='global':
        return f"Usage: {BIN_NAME} <--glob <GLOB>|--fail-no-files|--dry-run|--invert|--literal-string|--fail-any|--fail-none|--join-language-scopes|--line-numbers|--only-matching|--hidden|--gitignored|--sorted|--stdin-detection <STDIN_DETECTION>|--stdout-detection <STDOUT_DETECTION>|--threads <THREADS>|--verbose...> [SCOPE] [-- <REPLACEMENT>]"
    if o.group.startswith('lang:'):
        lang=o.group.split(':',1)[1]; vn=LANG_VALUE_NAMES[lang]
        return f"Usage: {BIN_NAME} <--{lang} <{vn}>|--{lang}-query <TREE-SITTER-QUERY-VALUE>|--{lang}-query-file <TREE-SITTER-QUERY-FILENAME>> [SCOPE] [-- <REPLACEMENT>]"
    if o.group=='german':
        return f"Usage: {BIN_NAME} <--german-prefer-original|--german-naive> [SCOPE] [-- <REPLACEMENT>]"
    return _usage()

def _unexpected_arg(arg, present_tokens=None):
    # arg like '--bogus' or '-x' or plain positional
    msg=f"error: unexpected argument '{arg}' found\n"
    usage=_usage()
    tips=[]
    if arg.startswith('--'):
        cand=[o.long for o in OPTS]+[a for o in OPTS for a in o.aliases]+['help','version']
        sim=similar(arg[2:],cand)
        if sim:
            tips.append(f"  tip: a similar argument exists: '--{sim}'")
            usage=_suggest_usage(sim)
    if arg.startswith('-'):
        tips.append(f"  tip: to pass '{arg}' as a value, use '-- {arg}'")
    if tips:
        msg+="\n"+"\n".join(tips)+"\n"
    msg+=f"\n{usage}\n"+_footer()
    err_exit(msg)

def _multiple_times(opt):
    name=opt.err_name() if opt else '[REPLACEMENT]'
    if opt is None:
        name='[REPLACEMENT]'
    err_exit(f"error: the argument '{name}' cannot be used multiple times\n\n{_usage()}\n"+_footer())

def _conflict_delete(args, present_tokens, scope_req=True, repl_used=False):
