VERSION="srgn 0.14.1\n"

class AppError(Exception):
    def __init__(self,text):
        self.text=text
class SomeInScope(Exception): pass
class NoInScope(Exception): pass
class ApplyFailure(Exception): pass  # message after "Error applying: "

LOG_LEVEL=1  # error
_LEVELS={'off':0,'error':1,'warn':2,'warning':2,'info':3,'debug':4,'trace':5}
def log_error(msg):
    if LOG_LEVEL>=1:
        ts=datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ')
        sys.stderr.write(f"[{ts} ERROR srgn] {msg}\n")
        sys.stderr.flush()

def init_logging(args):
    global LOG_LEVEL
    base=1
    env=os.environ.get('RUST_LOG')
    if env:
        # pick srgn= level if present else last comma token without = or with =
        chosen=None
        for part in env.split(','):
            part=part.strip()
            if not part: continue
            if '=' in part:
                k,v=part.split('=',1)
                if k.strip() in ('srgn','*'): chosen=v.strip().lower()
                elif chosen is None: chosen=v.strip().lower()
