def apply_action_text(ctx, seg):
    txt=seg.text
    for a in ctx.actions:
        if a=='replace':
            try: txt=actions.substitute_vars(ctx.replacement_template, seg.captures)
            except ReplacementApplyError as e:
                raise ApplyFailure(f"Error in an action: Action failed in replacement: Error in variable expressions: {e}")
        elif a=='upper': txt=actions.to_upper(txt)
        elif a=='lower': txt=actions.to_lower(txt)
        elif a=='titlecase': txt=actions.titlecase_text(txt)
        elif a=='normalize': txt=actions.normalize_text(txt)
        elif a=='symbols': txt=actions.symbols_text(txt,False)
        elif a=='symbols_inv': txt=actions.symbols_text(txt,True)
        elif a=='german': txt=actions.german_text(txt, naive=bool(ctx.args.vals.get('german_naive')), prefer_original=bool(ctx.args.vals.get('german_prefer_original')))
        elif a=='delete': txt=''
    return txt

def scope_text(ctx, text):
    segments=[Seg(text,True,None)]
    if ctx.lang_scopers:
        if ctx.args.vals.get('join_language_scopes'):
            # union of all language scopers on original in-segments
            def join_fn(seg):
                allranges=[]
                for fn in ctx.lang_scopers:
                    rs=fn(seg.text)
                    allranges.extend((s,e,seg.captures) for s,e in rs)
                return split_by_ranges(seg.text,allranges)
            segments=explode(segments,join_fn)
        else:
            for fn in ctx.lang_scopers:
                def make(fn):
                    return lambda seg: split_by_ranges(seg.text,[(s,e,seg.captures) for s,e in fn(seg.text)])
                segments=explode(segments,make(fn))
    # regex / literal scoper (always)
    if ctx.literal:
        needle=ctx.args.scope
        def lit(seg):
            if needle=='':
                return [Seg(seg.text,False)] if seg.text else []
            ranges=[]; pos=0
            while True:
                idx=seg.text.find(needle,pos)
                if idx==-1: break
                ranges.append((idx,idx+len(needle),None)); pos=idx+len(needle)
            return split_by_ranges(seg.text,ranges)
        segments=explode(segments,lit)
    else:
        def rgx(seg):
            rs=ctx.compiled.finditer_nonempty(seg.text)
            return split_by_ranges(seg.text,[(s,e,caps) for s,e,caps in rs])
        segments=explode(segments,rgx)
    return segments

def squeeze_segments(segments):
    out=[]; i=0
    # consecutive In segments with no Out segment between (our model: adjacent in list)
    prev_was_in=False
    for seg in segments:
        if seg.inn and prev_was_in:
            # drop this segment entirely
            continue
        out.append(seg)
        prev_was_in=seg.inn
        if not seg.inn and seg.text!='':
            prev_was_in=False
        elif not seg.inn and seg.text=='':
            pass
    return out

def apply_text(ctx, text):
    segments=scope_text(ctx,text)
    any_in=any(s.inn and s.text!='' for s in segments)
    if ctx.args.vals.get('fail_any') and any_in:
        raise SomeInScope()
    if (not any_in) and (ctx.args.vals.get('fail_none') or ctx.search_mode):
        raise NoInScope()
    if ctx.squeeze:
        segments=squeeze_segments(segments)
    pre=[s.clone() for s in segments]
    post=[s.clone() for s in segments]
    for s in post:
        if s.inn:
            s.text=apply_action_text(ctx,s)
    return {'pre':pre,'post':post,'any_in':any_in}

def segs_text(segments):
    return ''.join(s.text for s in segments)
