# ---------------- glob & ignore ----------------
def glob_to_regex(pat):
    # glob crate Pattern with require_literal_separator=False approximation
    out=[]; i=0
    while i<len(pat):
        c=pat[i]
        if c=='*':
            if pat.startswith('**',i):
                out.append('.*'); i+=2
                # consume following '/'? '**/' can match empty path prefix; '.*' plus '/' would require a slash. Handle by making slash optional when '**/'
                if i<len(pat) and pat[i]=='/':
                    out.append('/?'); i+=1
                continue
            out.append('.*'); i+=1; continue
        if c=='?':
            out.append('.'); i+=1; continue
        if c=='[':
            # parse class as validated earlier
            j=i+1; neg=False
            if j<len(pat) and pat[j]=='!': neg=True; j+=1
            start=j
            if j<len(pat) and pat[j]==']': j+=1
            while j<len(pat) and pat[j]!=']': j+=1
            content=pat[start:j]
            # escape for python, keep ranges
            content=content.replace('\\','\\\\')
            out.append('['+('^' if neg else '')+content+']'); i=j+1; continue
        out.append(re.escape(c)); i+=1
    return re.compile('^'+''.join(out)+'$',flags=re.DOTALL)

class IgnoreRule:
    def __init__(self,base,pattern,neg,dir_only,anchored):
        self.base=base; self.pattern=pattern; self.neg=neg; self.dir_only=dir_only; self.anchored=anchored
        self.regex=self._compile()
    def _compile(self):
        pat=self.pattern
        # wildmatch to regex matching path relative to base
        out=[]; i=0
        # Split special ** handling
        while i<len(pat):
            if pat.startswith('**/',i):
                out.append('(?:.*/)?'); i+=3; continue
            if pat.startswith('/**',i) and i+3==len(pat):
                out.append('(?:/.*)?'); i+=3; continue
            if pat.startswith('**',i):
                out.append('.*'); i+=2; continue
            c=pat[i]
            if c=='*': out.append('[^/]*'); i+=1; continue
            if c=='?': out.append('[^/]'); i+=1; continue
            if c=='[':
                j=i+1; neg=False
                if j<len(pat) and pat[j]=='!': neg=True; j+=1
                if j<len(pat) and pat[j]==']': j+=1
