def _rust_identifiers(text,st,pairs,items,types=False):
    type_ids=set(); n=len(st)
    for it in items:
        if it['kind'] in ('struct','enum','union','trait','type') and it['name_idx'] is not None:
            type_ids.add(it['name_idx'])
    def angle_close(i):
        depth=0; j=i
        while j<n:
            if st[j].text=='<': depth+=1
            elif st[j].text=='>':
                depth-=1
                if depth==0: return j
            elif st[j].text=='>>':
                depth-=2
                if depth<=0: return j
            j+=1
        return None
    def collect_chain(j, limit):
        # st[j] ident starts a type path; mark last segment, process generic args; return index after path
        segs=[j]; k=j
        while k+2<=limit and st[k+1].text=='::' and st[k+2].kind=='ident':
            # turbofish ::<...> ends chain before '<'
            segs.append(k+2); k+=2
        last=segs[-1]
        if st[last].text not in _RUST_KEYWORDS and st[last].text not in _RUST_PRIMITIVES:
            type_ids.add(last)
        k=last+1
        # generic args (could be ::<...> too)
        if k+1<=limit and st[k].text=='::' and st[k+1].text=='<':
            ci=angle_close(k+1)
            if ci is not None and ci<=limit:
                collect_region(k+2,ci-1); return ci+1
        if k<=limit and st[k].text=='<':
            ci=angle_close(k)
            if ci is not None and ci<=limit:
                collect_region(k+1,ci-1); return ci+1
        return k
    def collect_region(a,b):
        if a is None or b is None or a>b: return
        j=a
        while j<=b:
            t=st[j]
            if t.kind=='ident' and t.text not in _RUST_KEYWORDS and t.text not in _RUST_PRIMITIVES:
                if j> a and st[j-1].text=='::':
                    j+=1; continue
                if j>0 and st[j-1].text=='.':
                    j+=1; continue
                j=collect_chain(j,b); continue
            j+=1
    def region_until(start, stops):
        j=start; par=br=0
        while j<n:
            tt=st[j]
            if tt.text=='(': par+=1
            elif tt.text==')':
                if par==0 and ')' in stops: break
                par-=1
            elif tt.text=='[': br+=1
            elif tt.text==']':
                if br==0 and ']' in stops: break
                br-=1
            elif par==0 and br==0 and tt.text in stops:
                break
            j+=1
        return j-1
    # Generic parameter lists and type contexts in items
    for it in items:
        # generics after name (or after impl)
        name_idx=it.get('name_idx')
        cand=None
        if it['kind']=='impl': cand=it['kw']+1
        elif name_idx is not None: cand=name_idx+1
        if cand is not None and cand<n and st[cand].text=='<':
            ci=angle_close(cand)
            if ci is not None: collect_region(cand+1,ci-1)
        # where clause
        for k in range(it['a'],it['b']+1):
            if st[k].kind=='ident' and st[k].text=='where':
                endh=it['body_open']-1 if it.get('body_open') is not None else it['b']
                collect_region(k+1,endh); break
        if it['kind']=='impl':
            endh=it['body_open']-1 if it.get('body_open') is not None else it['b']
            hdr_start=it['kw']+1
            if hdr_start<n and st[hdr_start].text=='<':
                ci=angle_close(hdr_start); hdr_start=ci+1 if ci is not None else hdr_start
            collect_region(hdr_start,endh)
        if it['kind']=='trait':
            # supertrait bounds after ':' in header
            endh=it['body_open']-1 if it.get('body_open') is not None else it['b']
            collect_region(it['kw']+1,endh)
            # name itself already added; collect_region marks name chain too harmless
        if it['kind']=='type':
            j=it['kw']+1
            while j<=it['b'] and st[j].text!='=': j+=1
            collect_region(j+1,it['b']-1 if st[it['b']].text==';' else it['b'])
        if it['kind']=='struct':
            # tuple struct: first '(' after name/generics/where not body; contents are types
            j=(name_idx+1 if name_idx is not None else it['kw']+1)
            if j<n and st[j].text=='<':
                ci=angle_close(j); j=ci+1 if ci is not None else j
            if j<=it['b'] and st[j].text=='(':
                ci=find_matching(st,pairs,j)
                if ci is not None: collect_region(j+1,ci-1)
        if it['kind']=='enum' and it.get('body_open') is not None:
            bo=it['body_open']; bc=find_matching(st,pairs,bo)
            if bc is not None:
                for a,b in _split_top_level(st,bo+1,bc-1,','):
                    # tuple variant (...) contents are types
                    for k in range(a,b+1):
                        if st[k].text=='(':
                            ci=find_matching(st,pairs,k)
                            if ci is not None: collect_region(k+1,ci-1)
                            break
                        if st[k].text in ('{','='): break
    for i,t in enumerate(st):
        if t.text==':' and i+1<n and (i==0 or st[i-1].text!=':'):
            # type ascription / field / param / bound regions. Exclude :: handled; label ':' follows lifetime etc region may be expression but collect_region only marks chains as types which could false-positive in struct literal values.
            # Require previous token is identifier/lifetime/')'/']'/'>' (param/field names, generic params) and not a match/struct-lit context approximated by: segment after ':' contains a capitalized or generic-looking type before a value-ish operator.
            end=region_until(i+1, {',','=',';',')','{',']'})
            if end>=i+1:
                # Heuristic: only collect if region contains no string/number/call '(' immediately after a lowercase ident (values), OR previous token in a param/field position. Accept common type contexts if first meaningful tokens are &, *, (, [, <, dyn/impl/trait keywords or an identifier.
                collect_region(i+1,end)
        if t.text=='->' and i+1<n:
            end=region_until(i+1, {'{',';'})
            # stop at where keyword
            for k in range(i+1,end+1):
                if st[k].text=='where': end=k-1; break
            collect_region(i+1,end)
    # Struct literals and tuple struct constructors: capitalized path chain directly before '{' or '(' in expression positions
    for i,t in enumerate(st):
        if t.kind=='ident' and t.text[:1].isupper() and i+1<n and st[i+1].text=='{':
            prev=st[i-1] if i>0 else None
            if prev is None or prev.text in ('=','(', ',',':','[','=>','!','?','&&','||',';','{') or (prev.kind=='ident' and prev.text in ('return','let')):
                type_ids.add(i)
    if types:
        return [(st[i].start,st[i].end) for i in sorted(type_ids)]
    field_ids=set()
    def mark_fields_in_brace(bo,bc):
        if bo is None or bc is None: return
        seg_start=True; depth=0
        for k in range(bo+1,bc):
            tt=st[k]
            if tt.text in ('{','(','['): depth+=1; continue
            if tt.text in ('}',')',']'): depth-=1; continue
            if depth==0 and tt.text==',':
                seg_start=True; continue
            if depth==0 and seg_start:
                j=k
                if st[j].text=='pub':
                    j+=1
                    if j<bc and st[j].text=='(':
                        ci=find_matching(st,pairs,j); j=(ci+1 if ci is not None else j)
                if j<bc and st[j].kind=='ident' and j+1<bc and st[j+1].text==':':
                    field_ids.add(j)
                seg_start=False
    for it in items:
        if it['kind'] in ('struct','union') and it.get('body_open') is not None:
            mark_fields_in_brace(it['body_open'], find_matching(st,pairs,it['body_open']))
        if it['kind']=='enum' and it.get('body_open') is not None:
            eb=find_matching(st,pairs,it['body_open'])
            kk=it['body_open']+1
            while eb is not None and kk<eb:
                if st[kk].text=='{':
                    ci=find_matching(st,pairs,kk); mark_fields_in_brace(kk,ci); kk=ci+1 if ci else kk+1
                else: kk+=1
    for i,t in enumerate(st):
        if t.kind!='ident': continue
        if i>0 and st[i-1].text=='.':
            field_ids.add(i)
        if i+1<n and st[i+1].text==':' and i>0 and st[i-1].text in ('{',','):
            field_ids.add(i)
    out=[]
    for i,t in enumerate(st):
