for pat in ['*.py','**/*.py','sub/*.py','*','**','[a-c]*','[a-c]?.py','[!a]*.py','?.*','x-[0-9].*','sub/**','**/deep/*','*.{py,txt}','\\*.py','a?.py','**c.py','deep/*.py','*/c.py','-']:
