opts=[['-u'],['-l'],['-t'],['-n'],['-g'],['-S'],['-d'],['-s'],['-i'],['-L'],['-j'],['-H'],['--sorted'],['--dry-run'],['--fail-any'],['--python','strings'],['--python-query','(string) @x'],['--rust','fn'],['--glob','*.py'],['--threads','2'],['--german-naive']]
